package bootstrap

import (
	"github.com/rancago/framework/framework/Container"
	"github.com/rancago/framework/framework/Cache"
	"github.com/rancago/framework/framework/WebSocket"
	"github.com/rancago/framework/app/Services"
)

// Daftarkan Redis sebagai Singleton
app.Container.Singleton("redis", func(c *Container.Container) (interface{}, error) {
	mgr := Cache.NewRedisManager(&Cache.RedisConfig{
		Host: cfg.Redis.Host,
		Port: cfg.Redis.Port,
	})
	_ = mgr.Connect()
	return mgr, nil
})

// Daftarkan WebSocket Hub (bergantung pada Redis)
app.Container.Singleton("ws.hub", func(c *Container.Container) (interface{}, error) {
	redisRaw, _ := c.Resolve("redis")
	hub := WebSocket.NewHub(redisRaw.(*Cache.RedisManager))
	hub.StartRedisListener()
	go hub.Run()
	return hub, nil
})

// Daftarkan NotificationService
app.Container.Singleton("service.notification", func(c *Container.Container) (interface{}, error) {
	redisRaw, _ := c.Resolve("redis")
	hubRaw, _ := c.Resolve("ws.hub")
	return Services.NewNotificationService(
		redisRaw.(*Cache.RedisManager),
		hubRaw.(*WebSocket.Hub),
	), nil
})

// Alias: memungkinkan resolve via nama interface
app.Container.Alias("service.notification", "Contracts.NotificationService")

// Resolve menggunakan key konkret
redisRaw, err := container.Resolve("redis")

// Resolve menggunakan alias interface
svcRaw, err := container.Resolve("Contracts.NotificationService")

// MustResolve — panic jika tidak ditemukan (aman digunakan saat boot)
hub := container.MustResolve("ws.hub").(*WebSocket.Hub)

// Has — cek keberadaan binding
if container.Has("storage") {
	driver, _ := container.Resolve("storage")
	_ = driver
}

