import (
	"context"
	"github.com/rancago/framework/framework/Storage"
	"github.com/rancago/framework/app/Contracts"
)

func setupStorage() {
	diskCfgs := map[string]Contracts.StorageDiskConfig{
		"local":  {Driver: "memory"},
		"s3":     {Driver: "s3",     Endpoint: "s3.amazonaws.com",  Bucket: "my-bucket"},
		"minio":  {Driver: "minio",  Endpoint: "minio.example.com", Bucket: "uploads"},
		"gdrive": {Driver: "gdrive", Credentials: "/etc/creds.json"},
	}

	mgr := Storage.NewManager("local", diskCfgs)

	// OCP: daftarkan driver baru tanpa mengubah Manager
	mgr.RegisterFactory("minio", func(cfg Contracts.StorageDiskConfig) (Contracts.StorageDriver, error) {
		return NewMinioDriver(cfg.Endpoint, cfg.Key, cfg.Secret, cfg.Bucket), nil
	})

	// Gunakan default disk
	defaultDriver := mgr.DefaultDisk()
	_ = defaultDriver

	// Gunakan disk bernama
	s3Driver, err := mgr.Disk("s3")
	if err == nil {
		file, _ := s3Driver.Get(context.Background(), "reports/2026.pdf")
		_ = file
	}

	// Proxy untuk constructor injection tanpa ketergantungan pada Manager
	proxy := mgr.Proxy("minio")
	_ = proxy
}

