import (
	"time"
	"github.com/rancago/framework/internal/domain/valueobjects"
)

type User struct {
	ID              valueobjects.ID
	Name            string
	Email           valueobjects.Email
	PasswordHash    string
	AvatarURL       string
	Provider        string   // "google", "github", "facebook", ""
	ProviderID      string
	EmailVerifiedAt *time.Time
	Roles           []*Role
	Permissions     []*Permission
	CreatedAt       time.Time
	UpdatedAt       time.Time
}

// HasRole cek keanggotaan role
func (u *User) HasRole(roleName string) bool {
	for _, r := range u.Roles {
		if r.Name == roleName {
			return true
		}
	}
	return false
}

// HasPermission cek permission langsung + via role yang dimiliki
func (u *User) HasPermission(permName string) bool {
	for _, p := range u.Permissions {
		if p.Name == permName {
			return true
		}
	}
	for _, r := range u.Roles {
		for _, rp := range r.Permissions {
			if rp.Name == permName {
				return true
			}
		}
	}
	return false
}

// LoginWithProvider mengorkestrasi full OAuth2 flow
func (uc *UserInteractor) LoginWithProvider(
	ctx context.Context,
	providerName, code string,
) (*entities.User, error) {
	p, err := uc.socialite.Provider(providerName)
	if err != nil {
		return nil, derrors.New("user.socialite", derrors.ErrNotFound, err.Error())
	}
	tok, err := p.ExchangeCode(ctx, code)
	if err != nil {
		return nil, derrors.New("user.socialite", derrors.ErrUnauthorized, err.Error())
	}
	info, err := p.GetUserInfo(ctx, tok)
	if err != nil {
		return nil, derrors.New("user.socialite", derrors.ErrInternal, err.Error())
	}
	// Cari user lama atau buat baru
	user, err := uc.users.FindByProvider(ctx, providerName, info.ID)
	if err == nil && user != nil {
		return user, nil // user lama ditemukan
	}
	email, _ := valueobjects.NewEmail(info.Email)
	user = entities.NewUser(info.Name, email)
	user.Provider = providerName
	user.ProviderID = info.ID
	user.AvatarURL = info.AvatarURL
	user.EmailVerifiedAt = &user.CreatedAt
	return uc.users.Create(ctx, user)
}

