func (uc *NotificationInteractor) Send(
	ctx context.Context,
	userID, title, body string,
	channel entities.NotificationChannel,
	data map[string]string,
) (*entities.Notification, error) {
	// 1. Buat & simpan notifikasi ke repository
	n, _ := entities.NewNotification(userID, title, body, channel)
	saved, _ := uc.notifRepo.Create(ctx, n)

	// 2. Increment Redis unread counter
	if uc.cache != nil {
		cacheKey := fmt.Sprintf("notif:unread:%s", userID)
		uc.cache.Incr(ctx, cacheKey)
		uc.cache.Expire(ctx, cacheKey, 7*24*time.Hour)
	}

	// 3. Kirim real-time via WebSocket
	if uc.ws != nil {
		msg := driven.WebSocketMessage{
			Type:    "notification:new",
			Channel: fmt.Sprintf("user:%s", saved.UserID),
			Payload: map[string]interface{}{
				"id":    saved.ID.String(),
				"title": saved.Title,
				"body":  saved.Body,
			},
		}
		raw, _ := json.Marshal(msg)
		uc.ws.SendDirect(userID, raw)       // kirim ke user spesifik
		uc.ws.PublishChannel(msg.Channel, raw) // broadcast ke channel
	}
	return saved, nil
}

// PublishChannel mengirim pesan ke semua klien di channel,
// DAN mempublikasikan ke Redis agar node lain juga menerima.
func (h *Hub) PublishChannel(channel string, raw []byte) {
	h.mu.RLock()
	for c := range h.channels[channel] {
		select {
		case c.Send <- raw:
		default:
		}
	}
	h.mu.RUnlock()

	// Publish ke Redis untuk instance Hub lain (multi-node)
	if h.redis != nil {
		redisKey := "rancago:ws:" + channel
		h.redis.Publish(nil, redisKey, raw)
	}
}

// StartRedisListener subscribe ke channel broadcast global
func (h *Hub) StartRedisListener() {
	if h.redis == nil {
		return
	}
	go func() {
		h.redis.Subscribe(nil, "rancago:ws:broadcast", func(msg []byte) {
			h.Broadcast(msg) // relay ke semua klien lokal
		})
	}()
}

func (uc *NotificationInteractor) Send(
	ctx context.Context,
	userID, title, body string,
	channel entities.NotificationChannel,
	data map[string]string,
) (*entities.Notification, error) {
	// 1. Create & persist notification to repository
	n, _ := entities.NewNotification(userID, title, body, channel)
	saved, _ := uc.notifRepo.Create(ctx, n)

	// 2. Increment Redis unread counter
	if uc.cache != nil {
		cacheKey := fmt.Sprintf("notif:unread:%s", userID)
		uc.cache.Incr(ctx, cacheKey)
		uc.cache.Expire(ctx, cacheKey, 7*24*time.Hour)
	}

	// 3. Send real-time via WebSocket
	if uc.ws != nil {
		msg := driven.WebSocketMessage{
			Type:    "notification:new",
			Channel: fmt.Sprintf("user:%s", saved.UserID),
			Payload: map[string]interface{}{
				"id":    saved.ID.String(),
				"title": saved.Title,
				"body":  saved.Body,
			},
		}
		raw, _ := json.Marshal(msg)
		uc.ws.SendDirect(userID, raw)          // send to specific user
		uc.ws.PublishChannel(msg.Channel, raw) // broadcast to channel
	}
	return saved, nil
}

// PublishChannel sends to all clients in the channel,
// AND publishes to Redis so other nodes can relay it.
func (h *Hub) PublishChannel(channel string, raw []byte) {
	h.mu.RLock()
	for c := range h.channels[channel] {
		select {
		case c.Send <- raw:
		default:
		}
	}
	h.mu.RUnlock()

	// Publish to Redis for other Hub instances (multi-node)
	if h.redis != nil {
		redisKey := "rancago:ws:" + channel
		h.redis.Publish(nil, redisKey, raw)
	}
}

// StartRedisListener subscribes to the global broadcast channel
func (h *Hub) StartRedisListener() {
	if h.redis == nil {
		return
	}
	go func() {
		h.redis.Subscribe(nil, "rancago:ws:broadcast", func(msg []byte) {
			h.Broadcast(msg) // relay to all local clients
		})
	}()
}

