// Document adalah model GORM untuk pencarian semantik.
// Kolom Embedding adalah pgvector 1536-dimensi dengan HNSW cosine index.
type Document struct {
	ID         uint           `gorm:"primaryKey" json:"id"`
	Title      string         `gorm:"size:500;not null" json:"title"`
